  props: React.ComponentProps<typeof DatePicker>,
) => {
  let instance: DatePicker | null = null;
  const result = render(
    <DatePicker
      ref={(node) => {
        instance = node;
      }}
      {...props}
    />,
  );

  return { ...result, instance: instance as DatePicker | null };
